function addElementDetails(root,id,color,self=false){const glow=new THREE.MeshBasicMaterial({color,transparent:true,opacity:self?.46:.74});if(id==="fire"){[-.32,0,.32].forEach((x,i)=>{const f=new THREE.Mesh(new THREE.ConeGeometry(.18,.72,12),glow);f.position.set(x,1.9+.12*i,0);f.rotation.z=x*.7;root.add(f)})}else if(id==="water"){for(let i=0;i<4;i++){const b=new THREE.Mesh(new THREE.SphereGeometry(.18-i*.02,12,8),glow);const a=i*Math.PI*.5;b.position.set(Math.cos(a)*.88,.52+i*.18,Math.sin(a)*.88);root.add(b)}}else if(id==="lightning"){for(let i=0;i<4;i++){const bolt=new THREE.Mesh(new THREE.BoxGeometry(.08,.7,.08),glow);bolt.position.set((i-1.5)*.28,.85+(i%2)*.35,0);bolt.rotation.z=(i%2?.75:-.75);root.add(bolt)}}else if(id==="earth"){[-.55,.55].forEach(x=>{const s=new THREE.Mesh(new THREE.DodecahedronGeometry(.32,0),glow);s.position.set(x,.82,0);s.scale.y=.75;root.add(s)})}else if(id==="wind"){for(let i=0;i<3;i++){const r=new THREE.Mesh(new THREE.TorusGeometry(.88+i*.18,.025,8,54),glow);r.rotation.x=Math.PI/2;r.position.y=.15+i*.42;root.add(r)}}else if(id==="light"){const halo=new THREE.Mesh(new THREE.TorusGeometry(.55,.035,8,48),glow);halo.position.y=2.05;halo.rotation.x=Math.PI/2;root.add(halo)}else if(id==="darkness"){const hood=new THREE.Mesh(new THREE.TorusGeometry(.5,.08,8,32),glow);hood.position.y=1.55;hood.rotation.x=Math.PI/2;root.add(hood)}else if(id==="poison"){for(let i=0;i<6;i++){const a=i*Math.PI/3,spike=new THREE.Mesh(new THREE.ConeGeometry(.09,.48,8),glow);spike.position.set(Math.cos(a)*.72,.72,Math.sin(a)*.72);spike.rotation.z=Math.cos(a)*.8;spike.rotation.x=Math.sin(a)*.8;root.add(spike)}}}
function makeAvatar(p,self=false){const root=new THREE.Group(),id=p.element||"fire",color=elementColor(id),bodyMat=mat(id,p.oluo?.92:p.devil?.65:.28);let body;if(id==="fire"){body=new THREE.Mesh(new THREE.ConeGeometry(.82,2.25,22),bodyMat);body.position.y=.08}else if(id==="water"){body=new THREE.Mesh(new THREE.SphereGeometry(.88,24,16),bodyMat);body.scale.y=1.5}else if(id==="lightning"){body=new THREE.Mesh(new THREE.OctahedronGeometry(1.02,1),bodyMat);body.scale.y=1.65}else if(id==="earth"){body=new THREE.Mesh(new THREE.DodecahedronGeometry(1.02,0),bodyMat);body.scale.y=1.42}else if(id==="wind"){body=new THREE.Mesh(new THREE.TorusKnotGeometry(.54,.19,72,10),bodyMat);body.scale.set(1.3,1.82,1.3)}else if(id==="light"){body=new THREE.Mesh(new THREE.IcosahedronGeometry(.95,1),bodyMat);body.scale.y=1.5}else if(id==="darkness"){body=makeCapsuleBody(.58,1.48,bodyMat);body.scale.y=1.16}else{body=makeCapsuleBody(.54,1.35,bodyMat);body.scale.y=1.22}root.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.34,18,14),bodyMat);head.position.y=1.55;root.add(head);const ring=new THREE.Mesh(new THREE.TorusGeometry(1.06,.045,8,56),new THREE.MeshBasicMaterial({color,transparent:true,opacity:self?.46:.72}));ring.rotation.x=Math.PI/2;ring.position.y=-.82;root.add(ring);if(p.devil){const horns=new THREE.Group();[-.24,.24].forEach(x=>{const h=new THREE.Mesh(new THREE.ConeGeometry(.12,.45,8),new THREE.MeshBasicMaterial({color:0x210010}));h.position.set(x,1.92,0);horns.add(h)});root.add(horns)}if(p.evolve>=5){const aura=new THREE.Mesh(new THREE.TorusGeometry(1.32,.05,8,64),new THREE.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.58}));aura.rotation.x=Math.PI/2;aura.position.y=.72;root.add(aura)}if(p.oluo){const crown=new THREE.Mesh(new THREE.TorusKnotGeometry(.44,.055,64,6),new THREE.MeshBasicMaterial({color:0xfff5b6,transparent:true,opacity:.9}));crown.position.y=2.14;root.add(crown)};(p.secondaryElements||[]).slice(0,3).forEach((sid,i)=>{const c=elementColor(sid),g=sid==="water"?new THREE.SphereGeometry(.14,10,8):sid==="fire"?new THREE.ConeGeometry(.12,.3,9):sid==="lightning"?new THREE.OctahedronGeometry(.16,0):sid==="earth"?new THREE.DodecahedronGeometry(.16,0):new THREE.SphereGeometry(.13,8,6);const o=new THREE.Mesh(g,new THREE.MeshBasicMaterial({color:c,transparent:true,opacity:self?.5:.86}));const a=i*Math.PI*2/3;o.position.set(Math.cos(a)*1.2,.68+i*.2,Math.sin(a)*1.2);o.userData.orbit={base:a,rad:1.2,speed:1.1+i*.35,h:.68+i*.2};root.add(o)});addElementDetails(root,id,color,self);root.userData.element=id;root.userData.secondary=(p.secondaryElements||[]).join(",");root.userData.devil=!!p.devil;root.userData.oluo=!!p.oluo;root.userData.evolve=p.evolve||0;return root}
function refreshSelfVisual(){if(!scene)return;disposeObj(selfVisual);selfVisual=makeAvatar(local,true);selfVisual.scale.set(.36,.36,.36);scene.add(selfVisual)}
function refreshViewModel(){if(!camera)return;if(viewModel)camera.remove(viewModel);const id=local.element||"fire",color=elementColor(id),m=new THREE.MeshBasicMaterial({color,transparent:true,opacity:.82}),g=new THREE.Group(),left=new THREE.Mesh(new THREE.SphereGeometry(.075,12,8),m),right=new THREE.Mesh(new THREE.SphereGeometry(.075,12,8),m),core=new THREE.Mesh(new THREE.TorusGeometry(.11,.012,8,28),m);left.position.set(-.32,-.22,-.72);right.position.set(.32,-.22,-.72);core.position.set(0,-.18,-.88);core.rotation.x=Math.PI/2;g.add(left,right,core);viewModel=g;camera.add(viewModel)}
function updateAvatar(root,dt){const t=performance.now()*.001;root.children.forEach(o=>{if(o.userData.orbit){const a=o.userData.orbit.base+t*o.userData.orbit.speed;o.position.x=Math.cos(a)*o.userData.orbit.rad;o.position.z=Math.sin(a)*o.userData.orbit.rad;o.position.y=o.userData.orbit.h+Math.sin(t*2+a)*.08}});root.rotation.y+=dt*.8}
function visualChanged(mesh,p){return mesh.userData.element!==(p.element||"fire")||mesh.userData.secondary!==(p.secondaryElements||[]).join(",")||mesh.userData.devil!==!!p.devil||mesh.userData.oluo!==!!p.oluo||mesh.userData.evolve!==(p.evolve||0)}

function setSelectedCard(i){selectedCard=(i+4)%4;renderCards()}
function addEvents(){addEventListener("resize",()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});addEventListener("keydown",e=>{if(e.target?.id==="chatInput"){if(e.code==="Escape"){e.preventDefault();closeChat()}return}if(e.code==="Escape"&&!$("hud").classList.contains("hidden")){e.preventDefault();isPauseOpen()?closePauseMenu():openPauseMenu();return}if(isPauseOpen())return;if(e.code==="Enter"&&!$("hud").classList.contains("hidden")){e.preventDefault();openChat();return}keys[e.code]=true;if(/^Digit[1-4]$/.test(e.code))setSelectedCard(parseInt(e.code.at(-1))-1)});addEventListener("keyup",e=>{if(e.target?.id==="chatInput")return;keys[e.code]=false});addEventListener("wheel",e=>{if($("hud").classList.contains("hidden")||isPauseOpen()||e.target?.closest?.(".chat"))return;e.preventDefault();setSelectedCard(selectedCard+(e.deltaY>0?1:-1))},{passive:false});addEventListener("mousemove",e=>{if(isPauseOpen()||document.pointerLockElement!==document.body)return;local.rot.y-=e.movementX*.0022;local.rot.x=clamp(local.rot.x-e.movementY*.0022,-1.35,1.35)});addEventListener("mousedown",e=>{if(e.target?.closest?.(".chat")||isPauseOpen())return;if($("hud").classList.contains("hidden"))return;const cardNode=e.target?.closest?.(".card");if(cardNode)setSelectedCard(parseInt(cardNode.dataset.card)||0);if(cardNode&&e.button!==2)return;if(document.pointerLockElement!==document.body)lockPointer();if(e.button===0)castCard();if(e.button===2)startChargeSkill()});addEventListener("mouseup",e=>{if(e.button===2)releaseChargeSkill()});addEventListener("contextmenu",e=>e.preventDefault())}
function isUltimateCard(card,index){return index===3||card?.ultimate||card?.type==="궁극기"}
function cardInfo(card){const parts=[card.damage?"피해 "+Math.round(card.damage*local.power):"보조"];if(card.heal)parts.push("회복 "+Math.round(card.heal*local.power));if(card.shield)parts.push("방어 "+Math.round(card.shield*local.power));if(card.healCut)parts.push("회복감소 "+Math.round((1-Math.max(card.healCut,.4))*100)+"%");return parts.join(" · ")}
function rightHoldInfo(card,i){if(card.type==="공격")return"우클릭 지속공격";if(card.type==="CC기")return"우클릭 패링";if(card.type==="방어")return"우클릭 없음";if(local.element==="fire"&&i===3)return"우클릭 태양차징";return"우클릭 차징"}
function renderCards(){const e=elements[local.element]||elements.fire,cards=getCards(e);$("cards").innerHTML=cards.map((card,i)=>`<div class="card ${i===selectedCard?"active":""} ${local.charge&&local.chargeCard===i?"charging":""}" data-card="${i}" style="border-color:#${e.color.toString(16).padStart(6,"0")}"><h4>${card.name}</h4><p>${card.type} · 마나 ${card.mana}<br>${cardInfo(card)} · ${Math.max(.2,card.cd*local.cdMul).toFixed(1)}초<br>${rightHoldInfo(card,i)}</p></div>`).join("")}
function getCards(e){const arr=e.cards.map(x=>({...x}));if(arr[3])Object.assign(arr[3],{type:"궁극기",ultimate:true});if(local.evolve>=1&&arr[0])arr[0].damage=Math.round((arr[0].damage||0)*1.1);if(local.evolve>=2&&arr[1]){arr[1].shield=Math.round((arr[1].shield||0)*1.15);arr[1].heal=Math.round((arr[1].heal||0)*1.15)}if(local.evolve>=3&&arr[2]){arr[2].damage=Math.round((arr[2].damage||0)*1.15);if(arr[2].stun)arr[2].stun=Math.min(1.6,arr[2].stun*1.15);if(arr[2].slow)arr[2].slow*=1.15}if(local.evolve>=5)arr[3]={...arr[3],type:"궁극기",ultimate:true,name:"최종진화 " + arr[3].name,damage:Math.round((arr[3].damage||0)*1.2),shield:(arr[3].shield||0)+20,heal:(arr[3].heal||0)+15};if(local.devil)arr.forEach((x,i)=>{x.name="악마의 "+x.name;x.damage=Math.round((x.damage||0)*1.1);x.drain=(x.drain||.08)+.08;x.mana=Math.ceil((x.mana||0)*1.1);if(i===3){Object.assign(x,{type:"궁극기",ultimate:true});x.healCut=Math.max(.4,(x.healCut||.5)-.15)}});if(local.oluo){arr[0]={...arr[0],name:"올루오푸스의 손아귀",damage:20,mana:18,cd:1.4,drain:.1};arr[1]={...arr[1],name:"초월의 왕관",type:"방어",damage:0,mana:38,cd:18,shield:50,heal:0};arr[2]={...arr[2],name:"심연의 지배",type:"CC기",damage:18,mana:44,cd:22,stun:.8,slow:2};arr[3]={...arr[3],name:"강림: 세계 포식",type:"궁극기",ultimate:true,damage:75,mana:100,cd:65,healCut:.4,slow:2.5,pull:1}}return arr}
function animate(){gameLoop=requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.05);const r=getRoom();if(!r||r.phase!=="battle")return;updateLocal(dt,r);updateOpponents(r);updateEffects(dt);updateHud(r);updateNameplates(r);renderer.render(scene,camera)}
function constrainArenaPosition(pos){const d=Math.hypot(pos.x,pos.z);if(d>moveLimit){pos.x=pos.x/d*moveLimit;pos.z=pos.z/d*moveLimit}}
function healValue(v,actor=local){return Math.round(v*(now()<(actor.healCutUntil||0)?actor.healCutMul||.5:1))}
function healLocal(v){local.hp=clamp(local.hp+healValue(v),0,local.maxHp)}
function updateLocal(dt,r){
if(!local.alive||isPauseOpen())return;
const t=now(),stunned=t<local.stunUntil;
local.cooldowns=local.cooldowns.map(x=>Math.max(0,x-dt));
if(stunned&&local.charge)clearChargeSkill();
if(local.charge){
  local.chargeTime=(local.chargeTime||0)+dt;
  updateChargeSkill(dt,t);
  if(local.chargeMode!=="stream")local.mana=clamp(local.mana+manaRegenRate()*dt,0,local.maxMana);
}else local.mana=clamp(local.mana+manaRegenRate()*dt,0,local.maxMana);
const parrySlow=local.chargeMode==="parry"?.55:1,base=(t<local.speedUntil?9:6.5)*local.move*(t<local.slowUntil?.55:1)*parrySlow;let forward=0,strafe=0;
if(!stunned&&!local.dashState){if(keys.KeyW)forward+=1;if(keys.KeyS)forward-=1;if(keys.KeyA)strafe-=1;if(keys.KeyD)strafe+=1}
const len=Math.hypot(forward,strafe)||1,sy=Math.sin(local.rot.y),cy=Math.cos(local.rot.y),fx=-sy,fz=-cy,rx=cy,rz=-sy;
local.vel.x=(fx*forward/len+rx*strafe/len)*base;local.vel.z=(fz*forward/len+rz*strafe/len)*base;
if(keys.ShiftLeft&&!stunned){dash();keys.ShiftLeft=false}
if(keys.Space&&local.pos.y<=2.02&&!stunned&&!local.dashState){jump();keys.Space=false}
const dashing=updateDash(dt,t);local.vel.y-=20*dt;
if(!dashing){local.pos.x+=local.vel.x*dt;local.pos.z+=local.vel.z*dt;constrainArenaPosition(local.pos)}
local.pos.y+=local.vel.y*dt;if(local.pos.y<2){local.pos.y=2;local.vel.y=0}
camera.position.set(local.pos.x,local.pos.y,local.pos.z);
if(selfVisual){if(visualChanged(selfVisual,local)){refreshSelfVisual();refreshViewModel()}selfVisual.position.set(local.pos.x,local.pos.y-1.55,local.pos.z);selfVisual.rotation.y=local.rot.y;updateAvatar(selfVisual,dt)}
if(viewModel){viewModel.userData.kick=Math.max(0,(viewModel.userData.kick||0)-dt*1.8);viewModel.userData.pulse=Math.max(0,(viewModel.userData.pulse||0)-dt*2.4);viewModel.position.z=-(viewModel.userData.kick||0);viewModel.rotation.x=-(viewModel.userData.kick||0)*1.6;viewModel.rotation.z=Math.sin(performance.now()*.004)*.08+(viewModel.userData.pulse||0)}
camera.rotation.order="YXZ";camera.rotation.y=local.rot.y;camera.rotation.x=local.rot.x;
if(t-lastSync>90){patch({hp:local.hp,maxHp:local.maxHp,shield:local.shield,mana:Math.round(local.mana),pos:local.pos,rot:local.rot,alive:local.alive,cooldowns:[...(local.cooldowns||[0,0,0,0])],dashCdUntil:local.dashCdUntil||0,stunUntil:local.stunUntil||0,slowUntil:local.slowUntil||0,ccResistUntil:local.ccResistUntil||0,speedUntil:local.speedUntil||0,healCutUntil:local.healCutUntil||0,healCutMul:local.healCutMul||1,parryUntil:local.parryUntil||0,parryBonusUntil:local.parryBonusUntil||0,parryBonusStun:local.parryBonusStun||0,parryTarget:local.parryTarget||"",coins:local.coins,totalCoins:local.totalCoins||0,spent:local.spent||0,kills:local.kills||0,deaths:local.deaths||0,damageDone:local.damageDone||0,damageTaken:local.damageTaken||0,power:local.power,move:local.move,cdMul:local.cdMul,evolve:local.evolve,crowns:local.crowns,devil:local.devil,oluo:local.oluo,upgradeCounts:{...(local.upgradeCounts||{})},secondaryElements:local.secondaryElements||[]});lastSync=t}
}
function manaRegenRate(){return Math.min(12,6+(local.evolve>=4?1:0)+(local.oluo?2:0))}
function clearChargeSkill(){local.charge=false;local.chargeMode="";local.chargeTime=0;local.chargeTick=0;local.chargeFxTick=0;local.parryUntil=0;if($("cards")&&!$("hud").classList.contains("hidden"))renderCards()}
function startChargeSkill(){if(!local.alive||now()<local.stunUntil)return;const e=elements[local.element]||elements.fire,cards=getCards(e),card=cards[selectedCard];if(!card)return;if(card.type==="방어"){log("방어 카드는 우클릭 기능이 없습니다.");return}if(card.type==="공격")local.chargeMode="stream";else if(card.type==="CC기")local.chargeMode="parry";else if(local.element==="fire"&&selectedCard===3)local.chargeMode="sun";else local.chargeMode="charge";if(local.chargeMode==="sun"&&(local.cooldowns[3]||0)>0){log("궁극기 쿨타임입니다.");local.chargeMode="";return}local.charge=true;local.chargeCard=selectedCard;local.chargeTime=0;local.chargeTick=0;local.chargeFxTick=0;if(local.chargeMode==="parry")local.parryUntil=now()+220;renderCards();chargePreviewEffect(true);log(local.chargeMode==="stream"?"지속 공격 시작":local.chargeMode==="parry"?"패링 태세":local.chargeMode==="sun"?"태양 차징 시작":"마나 차징 시작")}
function releaseChargeSkill(){if(!local.charge)return;const held=local.chargeTime||0,cardIndex=local.chargeCard,mode=local.chargeMode;clearChargeSkill();if(mode==="sun"&&cardIndex===3&&held>.22)throwFireSun(held)}
function updateChargeSkill(dt,t){if(!local.charge||!scene)return;if(local.chargeMode==="stream"){local.chargeFxTick-=dt;local.chargeTick-=dt;if(local.chargeFxTick<=0){chargePreviewEffect(false);local.chargeFxTick=.065}if(local.chargeTick<=0){continuousAttackTick();local.chargeTick=.16}}else if(local.chargeMode==="parry"){local.parryUntil=t+220;local.chargeFxTick-=dt;if(local.chargeFxTick<=0){chargePreviewEffect(false);local.chargeFxTick=.12}}else{local.chargeFxTick-=dt;if(local.chargeFxTick<=0){chargePreviewEffect(false);local.chargeFxTick=.11}}}
function chargePreviewEffect(burst=false){if(!scene)return;const e=elements[local.element]||elements.fire,color=e.color,sy=Math.sin(local.rot.y),cy=Math.cos(local.rot.y),front={x:local.pos.x-sy*1.1,y:local.pos.y+.25,z:local.pos.z-cy*1.1};if(local.chargeMode==="sun"){const s=clamp(.55+(local.chargeTime||0)*.45,.55,1.45),sun=new THREE.Mesh(new THREE.SphereGeometry(s,24,16),effectMaterial(0xffb23a,.42));addEffect(sun,{x:front.x,y:front.y+1.1,z:front.z},burst?.55:.18,1.08);ringAt({x:front.x,y:front.y+1.1,z:front.z},0xfff08a,s*.9,burst?.55:.22);burstShape({x:front.x,y:front.y+1.1,z:front.z},0xff6a2a,burst?16:4,"flame",s*1.5)}else if(local.chargeMode==="stream"){const tip={x:front.x,y:front.y-.25,z:front.z};burstShape(tip,color,burst?12:4,local.element==="fire"?"flame":local.element==="earth"?"rock":local.element==="lightning"?"bolt":"bubble",burst?1.2:.65);if(burst)ringAt(tip,color,.55,.35)}else if(local.chargeMode==="parry"){const guard=new THREE.Mesh(new THREE.TorusGeometry(1.05,.055,8,64),effectMaterial(0xffffff,.62));guard.rotation.x=Math.PI/2;addEffect(guard,{x:local.pos.x,y:local.pos.y-.55,z:local.pos.z},burst?.45:.18,1.45);burstShape(front,0xffffff,burst?10:3,"spark",.85)}else{const aura=new THREE.Mesh(new THREE.TorusGeometry(.8,.045,8,56),effectMaterial(color,.6));aura.rotation.x=Math.PI/2;addEffect(aura,{x:local.pos.x,y:local.pos.y-.95,z:local.pos.z},burst?.55:.25,1.7)}}
function continuousAttackTick(){const e=elements[local.element]||elements.fire,base=getCards(e)[local.chargeCard],cost=Math.max(3,Math.round((base.mana||10)*.42));if(local.mana<cost){clearChargeSkill();log("마나 부족으로 지속 공격이 멈췄습니다.");return}local.mana=clamp(local.mana-cost,0,local.maxMana);const card={...base,name:"연속 "+base.name,mana:0,cd:.1,damage:Math.max(3,Math.round((base.damage||10)*.42)),stream:true};if(card.burn)card.burn=Math.max(2,Math.round(card.burn*.45));if(card.poison)card.poison=Math.max(2,Math.round(card.poison*.45));if(card.drain)card.drain=Math.min(.16,card.drain);if(card.slow)card.slow=Math.min(.65,card.slow*.45);const target=findTarget(card),hit=skillEndpoint(target,local,card);if(target)hitTarget(target,card,e);waterStreamEffect(hit,e,local);recordSkillFx(card,target);useCastMotion(card);patch({mana:Math.round(local.mana),parryUntil:0,cooldowns:[...(local.cooldowns||[0,0,0,0])]})}
