function throwFireSun(held){const e=elements.fire,base=getCards(e)[3],charge=clamp(held/1.8,.25,1),required=Math.max(35,Math.round((base.mana||70)*.55));if((local.cooldowns[3]||0)>0){log("궁극기 쿨타임입니다.");return}if(local.mana<required){log(`마나 부족: 태양 투척은 ${required} 마나가 필요합니다.`);return}const cost=Math.min(local.mana,Math.round(required+charge*24)),card={...base,name:"태양 투척",mana:cost,damage:Math.round((base.damage||42)*(1+charge*.8)),burn:(base.burn||0)+Math.round(8+charge*10),sun:true,charge};local.mana=clamp(local.mana-cost,0,local.maxMana);local.cooldowns[3]=Math.max(.8,base.cd*local.cdMul);const target=findTarget(card);if(target)hitTarget(target,card,e);sunProjectileEffect(local,skillEndpoint(target,local,card),e,charge);recordSkillFx(card,target);useCastMotion(card);patch({mana:Math.round(local.mana),cooldowns:[...(local.cooldowns||[0,0,0,0])],coins:local.coins,totalCoins:local.totalCoins||0,kills:local.kills||0});renderCards();log("태양 투척 사용")}
